/**
 * Minimal self-contained reproduction of WASM viewport/ring-buffer corruption.
 *
 * BUG: Writing escape-heavy output (~68 lines with SGR sequences) repeatedly
 * to a terminal causes the internal circular buffer to misindex after ~8 reps.
 *
 * Symptoms:
 * 1. getScrollbackLength() drops unexpectedly (e.g., 498 → 269) — the ring
 *    buffer's row tracking becomes incorrect.
 * 2. At certain column widths, getViewport() returns corrupted data where
 *    content from different lines is horizontally merged into one row.
 * 3. Both getViewport() and getLine() return the same wrong data.
 *
 * The corruption depends on column width (NOT data content):
 * - cols=80: OK    cols=120: CORRUPT    cols=130: CORRUPT
 * - cols=140: OK   cols=160: scrollback drops but viewport appears OK
 *   (row merge lands on empty rows)
 *
 * This is 100% self-contained — no external fixture files needed.
 */

import { describe, expect, test } from 'bun:test';
import type { Terminal } from './terminal';
import { createIsolatedTerminal } from './test-helpers';

const ESC = '\x1b';

/**
 * Generate escape-heavy terminal output similar to a color test script.
 * Produces ~68 lines with SGR 1/3/4/7, 256-color, and truecolor sequences.
 */
function generateTestOutput(): Uint8Array {
  const lines: string[] = [];

  // Bold banner with Unicode box-drawing characters
  lines.push(`${ESC}[1m${'═'.repeat(80)}${ESC}[0m`);
  lines.push('');

  // Section 1: 256-color palette blocks (8 rows of 32 colors)
  lines.push(`${ESC}[1m── COLORS ──${ESC}[0m`);
  for (let row = 0; row < 8; row++) {
    let line = '';
    for (let i = 0; i < 32; i++) {
      const idx = row * 32 + i;
      line += `${ESC}[48;5;${idx}m  ${ESC}[0m`;
    }
    lines.push(line);
  }

  // Section 2: Truecolor gradients (6 rows of 80 colored cells)
  lines.push(`${ESC}[1m── GRADIENTS ──${ESC}[0m`);
  for (let row = 0; row < 6; row++) {
    let line = '';
    for (let i = 0; i < 80; i++) {
      const r = Math.floor(Math.sin(i * 0.08 + row) * 127 + 128);
      const g = Math.floor(Math.sin(i * 0.08 + row + 2) * 127 + 128);
      const b = Math.floor(Math.sin(i * 0.08 + row + 4) * 127 + 128);
      line += `${ESC}[48;2;${r};${g};${b}m ${ESC}[0m`;
    }
    lines.push(line);
  }

  // Section 3: Text attributes
  lines.push(`${ESC}[1m── ATTRIBUTES ──${ESC}[0m`);
  lines.push(
    `  ${ESC}[1mBold${ESC}[0m ${ESC}[3mItalic${ESC}[0m ${ESC}[4mUnderline${ESC}[0m ${ESC}[7mReverse${ESC}[0m`
  );

  // Section 4: Unicode box drawing
  lines.push(`${ESC}[1m── UNICODE ──${ESC}[0m`);
  lines.push('  ┌──────────┬──────────┐');
  lines.push('  │  Cell A   │  Cell B   │');
  lines.push('  ├──────────┼──────────┤');
  lines.push('  │  Cell C   │  Cell D   │');
  lines.push('  └──────────┴──────────┘');

  // Sections 5-8: More colored text to reach ~68 lines
  for (let section = 0; section < 4; section++) {
    lines.push(`${ESC}[1m── SECTION ${section + 5} ──${ESC}[0m`);
    for (let row = 0; row < 8; row++) {
      let line = '  ';
      for (let i = 0; i < 60; i++) {
        const idx = (section * 64 + row * 8 + i) % 256;
        line += `${ESC}[38;5;${idx}m*${ESC}[0m`;
      }
      lines.push(line);
    }
  }

  // Final banner
  lines.push('');
  lines.push('═'.repeat(80));
  lines.push('  ✓ Test complete');
  lines.push('═'.repeat(80));
  lines.push('');

  return new TextEncoder().encode(lines.join('\r\n') + '\r\n');
}

function getViewportText(term: Terminal): string[] {
  const viewport = term.wasmTerm!.getViewport();
  const cols = term.cols;
  const rows: string[] = [];
  for (let row = 0; row < term.rows; row++) {
    let text = '';
    for (let col = 0; col < cols; col++) {
      const c = viewport[row * cols + col];
      if (c.width === 0) continue;
      text += c.codepoint > 32 ? String.fromCodePoint(c.codepoint) : ' ';
    }
    rows.push(text.trimEnd());
  }
  return rows;
}

describe('WASM ring buffer corruption — self-contained reproduction', () => {
  const data = generateTestOutput();

  /**
   * PRIMARY BUG INDICATOR: scrollbackLength should increase monotonically
   * when writing the same data repeatedly. The ring buffer corruption
   * causes it to jump backwards.
   */
  test('scrollbackLength increases monotonically after repeated writes', async () => {
    const term = await createIsolatedTerminal({ cols: 160, rows: 39, scrollback: 10000 });
    const container = document.createElement('div');
    term.open(container);

    const sbLengths: number[] = [];
    for (let rep = 0; rep < 12; rep++) {
      term.write(data);
      term.wasmTerm!.update();
      sbLengths.push(term.wasmTerm!.getScrollbackLength());
    }

    console.log('Scrollback lengths:', sbLengths);

    // Find non-monotonic drops
    let drops = 0;
    for (let i = 1; i < sbLengths.length; i++) {
      if (sbLengths[i] < sbLengths[i - 1]) {
        drops++;
        console.log(
          `Drop at rep ${i}: ${sbLengths[i - 1]} → ${sbLengths[i]} (delta ${sbLengths[i] - sbLengths[i - 1]})`
        );
      }
    }

    // Scrollback should never decrease when writing new data
    expect(drops).toBe(0);
    term.dispose();
  });

  /**
   * Viewport text should remain stable across repeated writes.
   * The old bug caused catastrophic row-merging (many rows corrupted at early reps).
   * After the fix, at most 1 row may show a trivial trailing-whitespace diff.
   */
  test('viewport text remains stable at cols=130 after repeated writes', async () => {
    const term = await createIsolatedTerminal({ cols: 130, rows: 39, scrollback: 10000 });
    const container = document.createElement('div');
    term.open(container);

    let baseline: string[] | null = null;
    let maxDiffRows = 0;

    for (let rep = 0; rep < 12; rep++) {
      term.write(data);
      term.wasmTerm!.update();
      const text = getViewportText(term);

      if (!baseline) {
        baseline = text;
      } else {
        let diffs = 0;
        for (let i = 0; i < Math.max(text.length, baseline.length); i++) {
          if ((text[i] || '') !== (baseline[i] || '')) {
            diffs++;
          }
        }
        if (diffs > maxDiffRows) maxDiffRows = diffs;
      }
    }

    // The old bug caused 10+ rows of corruption at early reps.
    // After the fix, at most 1 row may differ (trailing whitespace artifact).
    console.log(`Max diff rows across reps: ${maxDiffRows}`);
    expect(maxDiffRows).toBeLessThanOrEqual(1);
    term.dispose();
  });

  /**
   * getViewport and getLine agree — corruption is in the underlying
   * WASM state, not just in one API.
   */
  test('getViewport and getLine return identical (corrupted) data', async () => {
    const term = await createIsolatedTerminal({ cols: 130, rows: 39, scrollback: 10000 });
    const container = document.createElement('div');
    term.open(container);

    for (let rep = 0; rep < 12; rep++) {
      term.write(data);
      term.wasmTerm!.update();
    }

    const vpText = getViewportText(term);
    let matches = 0;
    for (let row = 0; row < term.rows; row++) {
      const line = term.wasmTerm?.getLine(row);
      if (!line) continue;
      const lnText = line
        .map((c) => String.fromCodePoint(c.codepoint || 32))
        .join('')
        .trimEnd();
      if (vpText[row] === lnText) matches++;
    }

    console.log(`${matches}/${term.rows} viewport rows match getLine`);
    expect(matches).toBe(term.rows);
    term.dispose();
  });

  /**
   * Column width affects whether the corruption is visible in viewport text.
   * The ring buffer always corrupts, but row merging is only detectable when
   * the misaligned rows contain different content.
   */
  test('column width sensitivity', async () => {
    const results: string[] = [];
    for (const cols of [80, 100, 120, 130, 140, 160]) {
      const term = await createIsolatedTerminal({ cols, rows: 39, scrollback: 10000 });
      const container = document.createElement('div');
      term.open(container);

      const sbLengths: number[] = [];
      let baseline: string[] | null = null;
      let vpCorrupt = false;

      for (let rep = 0; rep < 12; rep++) {
        term.write(data);
        term.wasmTerm!.update();
        sbLengths.push(term.wasmTerm!.getScrollbackLength());
        const text = getViewportText(term);
        if (!baseline) {
          baseline = text;
        } else {
          for (let i = 0; i < Math.max(text.length, baseline.length); i++) {
            if ((text[i] || '') !== (baseline[i] || '')) {
              vpCorrupt = true;
              break;
            }
          }
        }
      }

      let sbDrops = 0;
      for (let i = 1; i < sbLengths.length; i++) {
        if (sbLengths[i] < sbLengths[i - 1]) sbDrops++;
      }

      const line = `cols=${cols}: scrollback_drops=${sbDrops} viewport_corrupt=${vpCorrupt}`;
      results.push(line);
      console.log(line);
      term.dispose();
    }
  }, 60000);
});

/**
 * Terminal Scrolling Tests
 *
 * Test Isolation Pattern:
 * Uses createIsolatedTerminal() to ensure each test gets its own WASM instance.
 */

import { afterEach, beforeEach, describe, expect, test } from 'bun:test';
import type { Terminal } from './terminal';
import { createIsolatedTerminal } from './test-helpers';

describe('Terminal Scrolling', () => {
  let terminal: Terminal;
  let container: HTMLElement;

  beforeEach(async () => {
    container = document.createElement('div');
    document.body.appendChild(container);
    terminal = await createIsolatedTerminal({ cols: 80, rows: 24 });
    terminal.open(container);
  });

  afterEach(() => {
    if (terminal) {
      terminal.dispose();
    }
    if (container && document.body.contains(container)) {
      document.body.removeChild(container);
    }
  });

  describe('Normal Screen Mode', () => {
    test('should scroll viewport on wheel event in normal mode', async () => {
      // Fill with enough lines to create scrollback
      for (let i = 0; i < 50; i++) {
        terminal.write(`Line ${i}\r\n`);
      }

      // Initial viewport should be at bottom
      const initialViewportY = terminal.viewportY;

      // Simulate wheel up (negative deltaY)
      const wheelEvent = new WheelEvent('wheel', {
        deltaY: -100,
        bubbles: true,
        cancelable: true,
      });
      container.dispatchEvent(wheelEvent);

      // Viewport should have scrolled up (viewportY increases away from 0)
      expect(terminal.viewportY).toBeGreaterThan(initialViewportY);
    });

    test('should scroll down on positive deltaY', async () => {
      // Fill with scrollback
      for (let i = 0; i < 50; i++) {
        terminal.write(`Line ${i}\r\n`);
      }

      // Scroll up first
      terminal.scrollLines(-10);
      const scrolledUpViewportY = terminal.viewportY;

      // Simulate wheel down (positive deltaY)
      const wheelEvent = new WheelEvent('wheel', {
        deltaY: 100,
        bubbles: true,
        cancelable: true,
      });
      container.dispatchEvent(wheelEvent);

      // Viewport should have scrolled down (viewportY decreases towards 0)
      expect(terminal.viewportY).toBeLessThan(scrolledUpViewportY);
    });

    test('should not send data to application in normal mode', async () => {
      const dataSent: string[] = [];
      terminal.onData((data) => dataSent.push(data));

      // Simulate wheel event
      const wheelEvent = new WheelEvent('wheel', {
        deltaY: -100,
        bubbles: true,
        cancelable: true,
      });
      container.dispatchEvent(wheelEvent);

      // No data should be sent to application
      expect(dataSent).toEqual([]);
    });
  });

  describe('Alternate Screen Mode', () => {
    beforeEach(async () => {
      // Enter alternate screen mode (vim, less, htop, etc.)
      terminal.write('\x1B[?1049h');
    });

    test('should detect alternate screen mode', async () => {
      expect(terminal.wasmTerm?.isAlternateScreen()).toBe(true);
    });

    test('should send arrow up sequences on wheel up in alternate screen', async () => {
      const dataSent: string[] = [];
      terminal.onData((data) => dataSent.push(data));

      // Simulate wheel up (negative deltaY = -100, should send ~3 arrow ups)
      const wheelEvent = new WheelEvent('wheel', {
        deltaY: -100,
        bubbles: true,
        cancelable: true,
      });
      container.dispatchEvent(wheelEvent);

      // Should send arrow up sequences (ESC[A)
      expect(dataSent.length).toBeGreaterThan(0);
      expect(dataSent.every((data) => data === '\x1B[A')).toBe(true);
      expect(dataSent.length).toBeCloseTo(3, 1); // ~3 arrows per click
    });

    test('should send arrow down sequences on wheel down in alternate screen', async () => {
      const dataSent: string[] = [];
      terminal.onData((data) => dataSent.push(data));

      // Simulate wheel down (positive deltaY = +100)
      const wheelEvent = new WheelEvent('wheel', {
        deltaY: 100,
        bubbles: true,
        cancelable: true,
      });
      container.dispatchEvent(wheelEvent);

      // Should send arrow down sequences (ESC[B)
      expect(dataSent.length).toBeGreaterThan(0);
      expect(dataSent.every((data) => data === '\x1B[B')).toBe(true);
      expect(dataSent.length).toBeCloseTo(3, 1); // ~3 arrows per click
    });

    test('should not scroll viewport in alternate screen', async () => {
      const initialViewportY = terminal.viewportY;

      // Simulate wheel event
      const wheelEvent = new WheelEvent('wheel', {
        deltaY: -100,
        bubbles: true,
        cancelable: true,
      });
      container.dispatchEvent(wheelEvent);

      // Viewport should not have changed
      expect(terminal.viewportY).toBe(initialViewportY);
    });

    test('should cap arrow count at 5 per wheel event', async () => {
      const dataSent: string[] = [];
      terminal.onData((data) => dataSent.push(data));

      // Simulate very large wheel delta
      const wheelEvent = new WheelEvent('wheel', {
        deltaY: -1000, // Very large delta
        bubbles: true,
        cancelable: true,
      });
      container.dispatchEvent(wheelEvent);

      // Should cap at 5 arrows
      expect(dataSent.length).toBeLessThanOrEqual(5);
    });
  });

  describe('Mode Transitions', () => {
    test('should switch behavior when entering alternate screen', async () => {
      // Start in normal mode
      for (let i = 0; i < 30; i++) {
        terminal.write(`Line ${i}\r\n`);
      }

      // Scroll up in normal mode
      const wheelUpNormal = new WheelEvent('wheel', {
        deltaY: -100,
        bubbles: true,
        cancelable: true,
      });
      container.dispatchEvent(wheelUpNormal);
      const normalModeViewportY = terminal.viewportY;

      // Should have scrolled viewport
      expect(normalModeViewportY).toBeLessThan(terminal.rows);

      // Enter alternate screen
      terminal.write('\x1B[?1049h');

      const dataSent: string[] = [];
      terminal.onData((data) => dataSent.push(data));

      // Wheel should now send arrow keys
      const wheelUpAlt = new WheelEvent('wheel', {
        deltaY: -100,
        bubbles: true,
        cancelable: true,
      });
      container.dispatchEvent(wheelUpAlt);

      // Should have sent arrow keys, not scrolled
      expect(dataSent.length).toBeGreaterThan(0);
      expect(dataSent[0]).toBe('\x1B[A');
    });

    test('should switch back to viewport scrolling when exiting alternate screen', async () => {
      // Enter alternate screen
      terminal.write('\x1B[?1049h');
      expect(terminal.wasmTerm?.isAlternateScreen()).toBe(true);

      // Exit alternate screen
      terminal.write('\x1B[?1049l');
      expect(terminal.wasmTerm?.isAlternateScreen()).toBe(false);

      // Fill with lines
      for (let i = 0; i < 30; i++) {
        terminal.write(`Line ${i}\r\n`);
      }

      const dataSent: string[] = [];
      terminal.onData((data) => dataSent.push(data));

      const initialViewportY = terminal.viewportY;

      // Wheel should scroll viewport again
      const wheelEvent = new WheelEvent('wheel', {
        deltaY: -100,
        bubbles: true,
        cancelable: true,
      });
      container.dispatchEvent(wheelEvent);

      // Should have scrolled up, not sent data
      expect(dataSent.length).toBe(0);
      expect(terminal.viewportY).toBeGreaterThan(initialViewportY);
    });
  });

  describe('Custom Wheel Handler', () => {
    test('should respect custom wheel handler in both modes', async () => {
      let customHandlerCalled = false;
      terminal.attachCustomWheelEventHandler(() => {
        customHandlerCalled = true;
        return true; // Override default behavior
      });

      const wheelEvent = new WheelEvent('wheel', {
        deltaY: -100,
        bubbles: true,
        cancelable: true,
      });
      container.dispatchEvent(wheelEvent);

      expect(customHandlerCalled).toBe(true);
    });

    test('custom handler can delegate to default behavior', async () => {
      terminal.attachCustomWheelEventHandler(() => {
        return false; // Don't override, use default
      });

      // Enter alternate screen
      terminal.write('\x1B[?1049h');

      const dataSent: string[] = [];
      terminal.onData((data) => dataSent.push(data));

      const wheelEvent = new WheelEvent('wheel', {
        deltaY: -100,
        bubbles: true,
        cancelable: true,
      });
      container.dispatchEvent(wheelEvent);

      // Should still send arrow keys
      expect(dataSent.length).toBeGreaterThan(0);
      expect(dataSent[0]).toBe('\x1B[A');
    });
  });

  describe('Edge Cases', () => {
    test('should handle zero deltaY gracefully', async () => {
      const dataSent: string[] = [];
      terminal.onData((data) => dataSent.push(data));

      const wheelEvent = new WheelEvent('wheel', {
        deltaY: 0,
        bubbles: true,
        cancelable: true,
      });
      container.dispatchEvent(wheelEvent);

      // Should not send any data or crash
      expect(dataSent.length).toBe(0);
    });

    test('should handle very small deltaY values', async () => {
      const dataSent: string[] = [];
      terminal.onData((data) => dataSent.push(data));

      // Enter alternate screen
      terminal.write('\x1B[?1049h');

      const wheelEvent = new WheelEvent('wheel', {
        deltaY: -10, // Small delta, rounds to 0
        bubbles: true,
        cancelable: true,
      });
      container.dispatchEvent(wheelEvent);

      // Should not send any arrows (count is 0)
      expect(dataSent.length).toBe(0);
    });

    test('wasmTerm exists before open (headless-compatible)', async () => {
      const closedTerminal = await createIsolatedTerminal({ cols: 80, rows: 24 });

      // With headless-compatible design, wasmTerm exists immediately
      // This allows headless mode to work without open()
      expect(closedTerminal.wasmTerm).toBeDefined();

      // The terminal can process writes even before open()
      closedTerminal.wasmTerm!.write('Test');
      const line = closedTerminal.wasmTerm!.getLine(0);
      expect(line).toBeDefined();

      closedTerminal.dispose();
    });
  });
});

