      );

      simulateKey(container, createKeyEvent('ArrowUp', 'ArrowUp'));
      expect(dataReceived[0]).toBe('\x1b[A');
      dataReceived.length = 0;

      cursorApp = true;
      simulateKey(container, createKeyEvent('ArrowUp', 'ArrowUp'));
      expect(dataReceived[0]).toBe('\x1bOA');
      dataReceived.length = 0;

      cursorApp = false;
      simulateKey(container, createKeyEvent('ArrowUp', 'ArrowUp'));
      expect(dataReceived[0]).toBe('\x1b[A');
    });
